Buffer *initBuffer(size_t bufSize, size_t blkSize, Buffer *buf)
{
	/* Every block in the buffer is preceded by a one byte availability flag,
	 * so a slot occupies blkSize + 1 bytes. */
	buf->numIO = 0;
	buf->bufSize = bufSize;
	buf->blkSize = blkSize;
	buf->numAllBlk = buf->numFreeBlk = bufSize / (blkSize + 1);

	if ((buf->data = (unsigned char *)malloc(bufSize)) == NULL)
	{
		perror("Buffer Initialization Failed!\n");
		return NULL;
	}
	/* All the flags are set to BLOCK_AVAILABLE (0) by the memset. */
	memset(buf->data, 0, bufSize);

	return buf;
}

