unsigned char *getNewBlockInBuffer(Buffer *buf)
{
	unsigned char *blkPtr;
	size_t i;

	if (buf->numFreeBlk == 0)
	{
		perror("Failed to Get a New Block from the Buffer!\n");
		return NULL;
	}

	for (i = 0; i < buf->numAllBlk; i++)
	{
		blkPtr = buf->data + i * (buf->blkSize + 1);
		if (*blkPtr == BLOCK_AVAILABLE)
		{
			*blkPtr = BLOCK_UNAVAILABLE;
			buf->numFreeBlk--;
			return blkPtr + 1; /* skip the availability flag */
		}
	}

	perror("Failed to Get a New Block from the Buffer!\n");
	return NULL;
}

