unsigned char *readBlockFromDisk(unsigned int addr, Buffer *buf)
{
	unsigned char *blkPtr;
	char filename[40];
	FILE *fp;

	if ((blkPtr = getNewBlockInBuffer(buf)) == NULL)
		return NULL;

	sprintf(filename, "%d.blk", addr);

	if ((fp = fopen(filename, "rb")) == NULL)
	{
		perror("Reading Block Fails!\n");
		freeBlockInBuffer(blkPtr, buf);
		return NULL;
	}

	memset(blkPtr, 0, buf->blkSize);
	fread(blkPtr, buf->blkSize, 1, fp);
	fclose(fp);

	buf->numIO++; /* one more block has been transferred from the disk */

	return blkPtr;
}

