/*
 * extmem.c
 * Zhaonian Zou
 * Harbin Institute of Technology
 * Jun 22, 2011
 */

#include <stdlib.h>
#include <stdio.h>
#include <string.h> // added for memset
#include "extmem.h"

Buffer *initBuffer(size_t bufSize, size_t blkSize, Buffer *buf)
{
	/* Every block of the buffer is preceded by a one byte availability flag,
	 * hence a slot in the buffer occupies blkSize + 1 bytes. */
	buf->numIO = 0;
	buf->bufSize = bufSize;
	buf->blkSize = blkSize;
	buf->numAllBlk = buf->numFreeBlk = bufSize / (blkSize + 1);

	if ((buf->data = (unsigned char *)malloc(bufSize)) == NULL)
	{
		perror("Buffer Initialization Fails!\n");
		return NULL;
	}
	/* Zeroing the region also sets every flag to BLOCK_AVAILABLE. */
	memset(buf->data, 0, bufSize);

	return buf;
}

void freeBuffer(Buffer *buf)
{
	free(buf->data);
}

unsigned char *getNewBlockInBuffer(Buffer *buf)
{
	unsigned char *blkPtr;
	size_t i;

	if (buf->numFreeBlk == 0)
	{
		perror("Failed to Get a New Block from the Buffer!\n");
		return NULL;
	}

	for (i = 0; i < buf->numAllBlk; i++)
	{
		blkPtr = buf->data + i * (buf->blkSize + 1);
		if (*blkPtr == BLOCK_AVAILABLE)
		{
			*blkPtr = BLOCK_UNAVAILABLE;
			buf->numFreeBlk--;
			return blkPtr + 1; /* skip the availability flag */
		}
	}

	perror("Failed to Get a New Block from the Buffer!\n");
	return NULL;
}

void freeBlockInBuffer(unsigned char *blk, Buffer *buf)
{
	if (blk == NULL)
		return;

	/* The availability flag sits right in front of the block payload. */
	if (*(blk - 1) == BLOCK_UNAVAILABLE)
	{
		*(blk - 1) = BLOCK_AVAILABLE;
		buf->numFreeBlk++;
	}
}

int dropBlockOnDisk(unsigned int addr)
{
	char filename[40];

	sprintf(filename, "%d.blk", addr);

	if (remove(filename) == -1)
	{
		perror("Dropping Block Fails!\n");
		return -1;
	}

	return 0;
}

unsigned char *readBlockFromDisk(unsigned int addr, Buffer *buf)
{
	unsigned char *blkPtr;
	char filename[40];
	FILE *fp;

	if ((blkPtr = getNewBlockInBuffer(buf)) == NULL)
		return NULL;

	sprintf(filename, "%d.blk", addr);

	if ((fp = fopen(filename, "rb")) == NULL)
	{
		perror("Reading Block Fails!\n");
		freeBlockInBuffer(blkPtr, buf);
		return NULL;
	}

	memset(blkPtr, 0, buf->blkSize);
	fread(blkPtr, buf->blkSize, 1, fp);
	fclose(fp);

	buf->numIO++; /* one more block has been transferred from the disk */

	return blkPtr;
}

