using namespace std;

/* Payload capacity of a block: the last two integers of every block are
 * reserved, exactly as in the relation files written by genData.py --
 * a zero separator followed by the address of the next block of the chain
 * (0 marks the last block). */
#define BLK_CAPACITY (BLK_SIZE - 2 * PTR_SIZE)

/* State of the result block that is currently being filled by pushToWrite. */
static unsigned char *writeBlk = NULL; /* block held in the buffer, NULL if none */
static size_t writeUsed = 0;           /* payload bytes already used */
static unsigned int writeAddr = 0;     /* disk address of the pending block */

/* Terminate the pending block with (0, nextAddr) and flush it to the disk.
 * writeBlockToDisk releases the buffer slot for us. */
static void flushWriteBlk(Buffer *buf, unsigned int nextAddr)
{
	int zero = 0;

	memcpy(writeBlk + BLK_SIZE - 2 * PTR_SIZE, &zero, PTR_SIZE);
	memcpy(writeBlk + BLK_SIZE - PTR_SIZE, &nextAddr, PTR_SIZE);
	writeBlockToDisk(writeBlk, writeAddr, buf);

	writeAddr++;
	writeBlk = NULL;
	writeUsed = 0;
}

void pushToWrite(Buffer *buf, unsigned char *source, size_t size, unsigned int addr, bool reset, bool push)
{
	if (reset)
	{
		/* Start a brand new result sequence at addr. Any block that is still
		 * pending is dropped: the buffer it lived in may already be gone, so
		 * we only forget about it here. */
		writeBlk = NULL;
		writeUsed = 0;
		writeAddr = addr;
		return;
	}

	if (push)
	{
		/* Flush whatever is left; this block ends the chain. */
		if (writeBlk != NULL && writeUsed > 0)
			flushWriteBlk(buf, 0);
		return;
	}

	if (source == NULL || size == 0 || size > BLK_CAPACITY)
		return;

	/* The pending block cannot hold one more tuple: flush it and link it to
	 * its successor. Flushing lazily keeps the chain of next addresses valid. */
	if (writeBlk != NULL && writeUsed + size > BLK_CAPACITY)
		flushWriteBlk(buf, writeAddr + 1);

	if (writeBlk == NULL)
	{
		if ((writeBlk = getNewBlockInBuffer(buf)) == NULL)
		{
			perror("Writing Result Fails!\n");
			return;
		}
		memset(writeBlk, 0, BLK_SIZE);
		writeUsed = 0;
	}

	memcpy(writeBlk + writeUsed, source, size);
	writeUsed += size;
}

