input.new_string:
/* One block of a hash partition holds HASH_PER_BLK tuples, the number of
 * tuples that are actually stored, and the address of the next block of the
 * partition (0 for the last one). Every bucket keeps its own pending block,
 * BUCKET_NUM + 1 blocks are therefore needed in the buffer while
 * partitioning, which fits in the 8 blocks the buffer provides. */
#define HASH_CNT_OFFSET (HASH_PER_BLK * 2 * PTR_SIZE)
/* Partitions are spread out so that every bucket may grow independently. */
#define HASH_BUCKET_STEP 100

static unsigned char *hashBlk[BUCKET_NUM] = { NULL };
static int hashCnt[BUCKET_NUM] = { 0 };
static unsigned int hashAddr[BUCKET_NUM] = { 0 };

/* Complete the pending block of bucket i and flush it to the disk. */
static void flushHashBlk(Buffer *buf, int i, unsigned int nextAddr)
{
	memcpy(hashBlk[i] + HASH_CNT_OFFSET, &hashCnt[i], PTR_SIZE);
	memcpy(hashBlk[i] + BLK_SIZE - PTR_SIZE, &nextAddr, PTR_SIZE);
	writeBlockToDisk(hashBlk[i], hashAddr[i], buf);

	hashAddr[i]++;
	hashBlk[i] = NULL;
	hashCnt[i] = 0;
}

void pushHashToWrite(Buffer *buf, Relation *R, unsigned int addr, bool reset, bool push)
{
	if (reset)
	{
		/* Bucket i is stored in the chain of blocks that starts at
		 * addr + i * HASH_BUCKET_STEP. */
		for (int i = 0; i < BUCKET_NUM; i++)
		{
			hashBlk[i] = NULL;
			hashCnt[i] = 0;
			hashAddr[i] = addr + i * HASH_BUCKET_STEP;
		}
		return;
	}

	if (push)
	{
		/* Flush the last block of every bucket. */
		for (int i = 0; i < BUCKET_NUM; i++)
			if (hashBlk[i] != NULL && hashCnt[i] > 0)
				flushHashBlk(buf, i, 0);
		return;
	}

	if (R == NULL)
		return;

	int bucket = R->attr1 % BUCKET_NUM; /* hash function on the join attribute */

	if (hashBlk[bucket] != NULL && hashCnt[bucket] >= HASH_PER_BLK)
		flushHashBlk(buf, bucket, hashAddr[bucket] + 1);

	if (hashBlk[bucket] == NULL)
	{
		if ((hashBlk[bucket] = getNewBlockInBuffer(buf)) == NULL)
		{
			perror("Writing Hash Partition Fails!\n");
			return;
		}
		memset(hashBlk[bucket], 0, BLK_SIZE);
		hashCnt[bucket] = 0;
	}

	unsigned char *slot = hashBlk[bucket] + hashCnt[bucket] * 2 * PTR_SIZE;
	memcpy(slot, &R->attr1, PTR_SIZE);
	memcpy(slot + PTR_SIZE, &R->attr2, PTR_SIZE);
	hashCnt[bucket]++;
}

