/* Remove the blanks that surround a (sub)query or a predicate. */
static string trim(string s)
{
	size_t begin = s.find_first_not_of(" \t\n\r");
	if (begin == string::npos)
		return "";
	size_t end = s.find_last_not_of(" \t\n\r");
	return s.substr(begin, end - begin + 1);
}

/* Index of the ')' that closes the '(' at position lp, npos if unbalanced. */
static size_t matchParen(const string &s, size_t lp)
{
	int depth = 0;
	for (size_t i = lp; i < s.size(); i++)
	{
		if (s[i] == '(')
			depth++;
		else if (s[i] == ')' && --depth == 0)
			return i;
	}
	return string::npos;
}

/* Position of the JOIN keyword that is not nested in any parentheses. */
static size_t findTopLevelJoin(const string &s)
{
	int depth = 0;
	for (size_t i = 0; i < s.size(); i++)
	{
		if (s[i] == '(')
			depth++;
		else if (s[i] == ')')
			depth--;
		else if (depth == 0 && s.compare(i, 4, "JOIN") == 0)
			return i;
	}
	return string::npos;
}

/* Parse query and hang the resulting subtree under root->left. */
void parseQuery(TreeNode *root, string query)
{
	query = trim(query);
	if (root == NULL || query.empty())
		return;

	/* a fully parenthesised (sub)query: drop the outermost pair */
	if (query[0] == '(' && matchParen(query, 0) == query.size() - 1)
	{
		parseQuery(root, query.substr(1, query.size() - 2));
		return;
	}

	/* SELECT [ predicate ] ( operand )  /  PROJECTION [ attributes ] ( operand ) */
	if (query.compare(0, 6, "SELECT") == 0 || query.compare(0, 10, "PROJECTION") == 0)
	{
		string type = (query.compare(0, 6, "SELECT") == 0) ? "SELECT" : "PROJECTION";
		size_t lb = query.find('[');
		size_t rb = query.find(']', lb == string::npos ? 0 : lb);
		size_t lp = query.find('(', rb == string::npos ? 0 : rb);
		size_t rp = (lp == string::npos) ? string::npos : matchParen(query, lp);

		if (lb == string::npos || rb == string::npos || lp == string::npos || rp == string::npos)
			return; /* malformed query */

		TreeNode *node = new TreeNode(type, trim(query.substr(lb + 1, rb - lb - 1)));
		root->left = node;
		/* the single operand of SELECT / PROJECTION becomes its left child */
		parseQuery(node, query.substr(lp + 1, rp - lp - 1));
		return;
	}

	/* operand JOIN operand */
	size_t join = findTopLevelJoin(query);
	if (join != string::npos)
	{
		TreeNode *node = new TreeNode("JOIN");
		root->left = node;

		TreeNode leftHolder, rightHolder;
		parseQuery(&leftHolder, query.substr(0, join));
		parseQuery(&rightHolder, query.substr(join + 4));
		node->left = leftHolder.left;
		node->right = rightHolder.left;
		return;
	}

	/* nothing left but the name of a relation */
	root->left = new TreeNode("LEAF", query);
}

