/* Break a conjunction "p1 & p2 & ..." into its single predicates. */
static vector<string> splitPredicates(const string &info)
{
	vector<string> preds;
	size_t begin = 0;

	while (begin <= info.size())
	{
		size_t amp = info.find('&', begin);
		string pred = trim(info.substr(begin, amp == string::npos ? string::npos : amp - begin));
		if (!pred.empty())
			preds.push_back(pred);
		if (amp == string::npos)
			break;
		begin = amp + 1;
	}

	return preds;
}

/* The attribute a predicate constrains, i.e. its left hand side. */
static string predAttr(const string &pred)
{
	size_t op = pred.find_first_of("=<>!");
	return trim(op == string::npos ? pred : pred.substr(0, op));
}

/* Names of every relation that occurs in a subtree. */
static void collectRelations(TreeNode *node, vector<string> &rels)
{
	if (node == NULL)
		return;
	if (node->type == "LEAF")
		rels.push_back(node->info);
	collectRelations(node->left, rels);
	collectRelations(node->right, rels);
}

/* How strongly an attribute looks like it belongs to a relation. The schemas
 * used in the lab name their attributes after the relation they belong to
 * (ENAME in EMPLOYEE, DNAME in DEPARTMENT, ...), so the length of the common
 * prefix is a usable affinity; 0 means "no idea". */
static size_t affinity(const string &attr, const string &rel)
{
	size_t i = 0;
	while (i < attr.size() && i < rel.size() && attr[i] == rel[i])
		i++;
	return i;
}

static size_t bestAffinity(const string &attr, const vector<string> &rels)
{
	size_t best = 0;
	for (size_t i = 0; i < rels.size(); i++)
	{
		size_t a = affinity(attr, rels[i]);
		if (a > best)
			best = a;
	}
	return best;
}

/* A SELECT may only sink below a PROJECTION when the projection still keeps
 * the attribute the predicate needs. */
static bool projectionKeeps(const string &list, const string &attr)
{
	size_t begin = 0;

	while (begin <= list.size())
	{
		size_t comma = list.find(',', begin);
		string item = trim(list.substr(begin, comma == string::npos ? string::npos : comma - begin));
		if (item == attr || item == "*")
			return true;
		if (comma == string::npos)
			break;
		begin = comma + 1;
	}

	return false;
}

/* Put one SELECT node per predicate on top of node, keeping the original
 * order of the predicates from the outermost one inwards. */
static TreeNode *wrapSelects(TreeNode *node, const vector<string> &preds)
{
	for (size_t i = preds.size(); i > 0; i--)
	{
		TreeNode *sel = new TreeNode("SELECT", preds[i - 1]);
		sel->left = node;
		node = sel;
	}
	return node;
}

TreeNode *optimizeQuery(TreeNode *root, vector<string> info)
{
	if (root == NULL)
		return NULL;

	/* info holds the predicates that are on their way down the tree. */

	if (root->type == "SELECT")
	{
		/* cascade of a conjunctive predicate: every conjunct travels on its
		 * own, the node itself is rebuilt as deep in the tree as possible */
		vector<string> preds = splitPredicates(root->info);
		info.insert(info.end(), preds.begin(), preds.end());
		return optimizeQuery(root->left, info);
	}

	if (root->type == "PROJECTION")
	{
		/* a selection is pushed below the projection only if the attribute it
		 * tests survives the projection */
		vector<string> down, stay;
		for (size_t i = 0; i < info.size(); i++)
		{
			if (projectionKeeps(root->info, predAttr(info[i])))
				down.push_back(info[i]);
			else
				stay.push_back(info[i]);
		}
		root->left = optimizeQuery(root->left, down);
		return wrapSelects(root, stay);
	}

	if (root->type == "JOIN")
	{
		/* each predicate is pushed to the operand that owns its attribute;
		 * predicates that cannot be attributed to one single operand remain
		 * above the join */
		vector<string> leftRels, rightRels, leftPreds, rightPreds, stay;
		collectRelations(root->left, leftRels);
		collectRelations(root->right, rightRels);

		for (size_t i = 0; i < info.size(); i++)
		{
			string attr = predAttr(info[i]);
			size_t l = bestAffinity(attr, leftRels);
			size_t r = bestAffinity(attr, rightRels);
			if (l > r)
				leftPreds.push_back(info[i]);
			else if (r > l)
				rightPreds.push_back(info[i]);
			else
				stay.push_back(info[i]);
		}

		root->left = optimizeQuery(root->left, leftPreds);
		root->right = optimizeQuery(root->right, rightPreds);
		return wrapSelects(root, stay);
	}

	/* LEAF: the predicates cannot go any deeper */
	return wrapSelects(root, info);
}

