using namespace std;

/* Blocks the buffer can hold, i.e. M of the M-way merge sort. */
#define MERGE_M (BUF_SIZE / (BLK_SIZE + 1))
/* M - 1 blocks are read at a time, the remaining one collects the output. */
#define SEG_BLK_NUM (MERGE_M - 1)
/* Upper bound on the number of runs a relation may be split into. */
#define MAX_SEG_NUM S_BLK_NUM

/* Tuples are ordered on the join attribute, ties broken on the second one. */
static bool cmpTuple(const Relation &a, const Relation &b)
{
	if (a.attr1 != b.attr1)
		return a.attr1 < b.attr1;
	return a.attr2 < b.attr2;
}

/* Two-pass multi-way merge sort of R (choice == SORT_R) or S (choice == SORT_S).
 * The sorted relation is left on the disk starting at MERGE_R_RET_ADDR resp.
 * MERGE_S_RET_ADDR, the sorted runs of the first pass at MERGE_?_SEG_ADDR. */
int mergeSort(Buffer *buf, bool choice)
{
	unsigned int srcAddr = choice == SORT_S ? S_ADDR : R_ADDR;
	unsigned int segAddr = choice == SORT_S ? MERGE_S_SEG_ADDR : MERGE_R_SEG_ADDR;
	unsigned int retAddr = choice == SORT_S ? MERGE_S_RET_ADDR : MERGE_R_RET_ADDR;
	int blkNum = choice == SORT_S ? S_BLK_NUM : R_BLK_NUM;
	const char *name = choice == SORT_S ? "S" : "R";

	int segNum = (blkNum + SEG_BLK_NUM - 1) / SEG_BLK_NUM;

	/* ---------- pass 1: generate the sorted runs ---------- */
	Relation tuples[SEG_BLK_NUM * TUPLE_PER_BLK];
	unsigned char *blks[SEG_BLK_NUM];

	pushToWrite(buf, NULL, 0, segAddr, true);

	for (int seg = 0; seg < segNum; seg++)
	{
