	if (segNum > MERGE_M - 1)
	{
		/* one block per run plus one output block have to fit in the buffer */
		cout << "Too many runs for a two pass merge sort!" << endl;
		return -1;
	}

	unsigned char *segBlk[MAX_SEG_NUM];    /* head block of every run */
	Relation segTuple[MAX_SEG_NUM][TUPLE_PER_BLK];
	int segPos[MAX_SEG_NUM];               /* tuple to be consumed next */
	int segNextBlk[MAX_SEG_NUM];           /* next block of the run to be read */
	int segEndBlk[MAX_SEG_NUM];            /* first block behind the run */
	bool segAlive[MAX_SEG_NUM];

	pushToWrite(buf, NULL, 0, retAddr, true);

	for (int seg = 0; seg < segNum; seg++)
	{
		segNextBlk[seg] = seg * SEG_BLK_NUM;
		segEndBlk[seg] = min(blkNum, segNextBlk[seg] + SEG_BLK_NUM);
		if ((segBlk[seg] = readBlockFromDisk(segAddr + segNextBlk[seg]++, buf)) == NULL)
			return -1;
		readTuplesFromBlock(segBlk[seg], segTuple[seg]);
		segPos[seg] = 0;
		segAlive[seg] = true;
	}

	int num = 0;
	while (true)
	{
		/* pick the smallest tuple among the heads of the runs */
		int best = -1;
		for (int seg = 0; seg < segNum; seg++)
		{
			if (!segAlive[seg])
				continue;
			if (best == -1 || cmpTuple(segTuple[seg][segPos[seg]], segTuple[best][segPos[best]]))
				best = seg;
		}
		if (best == -1)
			break; /* every run has been drained */

		pushToWrite(buf, (unsigned char *)&segTuple[best][segPos[best]], sizeof(Relation), retAddr);
		num++;

		if (++segPos[best] >= TUPLE_PER_BLK)
		{
			/* the head block of that run is exhausted, load its successor */
			freeBlockInBuffer(segBlk[best], buf);
			segBlk[best] = NULL;
			if (segNextBlk[best] < segEndBlk[best])
			{
				if ((segBlk[best] = readBlockFromDisk(segAddr + segNextBlk[best]++, buf)) == NULL)
					return -1;
				readTuplesFromBlock(segBlk[best], segTuple[best]);
				segPos[best] = 0;
			}
			else
				segAlive[best] = false;
		}
	}

	pushToWrite(buf, NULL, 0, retAddr, false, true);

	cout << "Relation " << name << ": " << num << " tuples sorted, result at "
	     << retAddr << " - " << retAddr + blkNum - 1 << endl;

	return 0;
}

