//
// Test driver for the QueryProcessing lab: runs one operator per invocation so
// that the on-disk results can be verified independently (see check.py).
//
// usage: test_main <sort_r|sort_s|select|project|nlj|hj|smj>
//
#include <iostream>
#include <string>
#include <stdio.h>
#include "extmem.h"
#include "file.h"
#include "blkio.h"
#include "select.h"
#include "project.h"
#include "join.h"
#include "mergeSort.h"

using namespace std;

int main(int argc, char **argv)
{
	if (argc < 2) {
		cerr << "usage: test_main <sort_r|sort_s|select|project|nlj|hj|smj>" << endl;
		return 2;
	}
	string cmd = argv[1];

	// remove stale result files, exactly like the interactive program does
	char filename[40];
	for (int i = SELECT_RET_ADDR; i < HASH_S_ADDR + OFFSET; i++) {
		sprintf(filename, "%d.blk", i);
		remove(filename);
	}

	Buffer buf;
	if (!initBuffer(BUF_SIZE, BLK_SIZE, &buf)) {
		perror("Buffer Initialization Failed!\n");
		return -1;
	}
	pushToWrite(&buf, NULL, 0, 500000, true);

	int ret = 0;
	if (cmd == "sort_r") ret = mergeSort(&buf, SORT_R);
	else if (cmd == "sort_s") ret = mergeSort(&buf, SORT_S);
	else if (cmd == "select") ret = select(&buf);
	else if (cmd == "project") ret = project(&buf);
	else if (cmd == "nlj") ret = nestedLoopJoin(&buf);
	else if (cmd == "hj") ret = hashJoin(&buf);
	else if (cmd == "smj") ret = sortMergeJoin(&buf);
	else { cerr << "unknown command " << cmd << endl; return 2; }

	cout << "[test] free blocks in buffer: " << buf.numFreeBlk << "/" << buf.numAllBlk
	     << " numIO: " << buf.numIO << endl;
	if (buf.numFreeBlk != buf.numAllBlk)
		cout << "[test] WARNING: buffer blocks leaked!" << endl;

	freeBuffer(&buf);
	return ret;
}

