using namespace std;

/* Blocks the buffer can hold. */
#define NLJ_M (BUF_SIZE / (BLK_SIZE + 1))
/* M - 1 blocks of the outer relation are joined against S at a time, the
 * remaining block is shared by the inner scan and the result writer. */
#define OUTER_BLK_NUM (NLJ_M - 1)

/* Block nested loop join of R and S on R.A = S.C. */
int nestedLoopJoin(Buffer *buf)
{
	Relation outer[OUTER_BLK_NUM * TUPLE_PER_BLK];
	unsigned char *blks[OUTER_BLK_NUM];
	int num = 0;

	pushToWrite(buf, NULL, 0, NLJ_RET_ADDR, true);
	cout << "Result of R and S joined on R.A = S.C:" << endl;

	for (int begin = 0; begin < R_BLK_NUM; begin += OUTER_BLK_NUM)
	{
		int end = begin + OUTER_BLK_NUM;
		if (end > R_BLK_NUM)
			end = R_BLK_NUM;

		/* ---------- outer scan: buffer M - 1 blocks of R ---------- */
		int outerNum = 0;
		for (int i = begin; i < end; i++)
		{
			if ((blks[i - begin] = readBlockFromDisk(R_ADDR + i, buf)) == NULL)
				return -1;
			readTuplesFromBlock(blks[i - begin], outer + outerNum);
			outerNum += TUPLE_PER_BLK;
		}
		/* the tuples are held in main memory now, the slots are given back so
		 * that the inner scan and the result writer can use them */
		for (int i = begin; i < end; i++)
			freeBlockInBuffer(blks[i - begin], buf);
	}

	return num;
}

