using namespace std;

/* Address of the first block of bucket i, see pushHashToWrite. */
#define HASH_BUCKET_ADDR(base, i) ((base) + (i) * 100)

/* An empty bucket has no block at all on the disk. */
static bool blockExists(unsigned int addr)
{
	string filename = to_string(addr) + ".blk";
	return access(filename.c_str(), F_OK) == 0;
}

/* Partition a whole relation of blkNum blocks into BUCKET_NUM buckets. */
static int partition(Buffer *buf, unsigned int srcAddr, int blkNum, unsigned int hashAddr)
{
	Relation tuples[TUPLE_PER_BLK];

	pushHashToWrite(buf, NULL, hashAddr, true);

	for (int i = 0; i < blkNum; i++)
	{
		unsigned char *blk = readBlockFromDisk(srcAddr + i, buf);
		if (blk == NULL)
			return -1;
		readTuplesFromBlock(blk, tuples);

		for (int j = 0; j < TUPLE_PER_BLK; j++)
			pushHashToWrite(buf, &tuples[j], hashAddr);

		freeBlockInBuffer(blk, buf);
	}

	/* flush the last block of every bucket */
	pushHashToWrite(buf, NULL, hashAddr, false, true);

	return 0;
}

/* Hash join of R and S on R.A = S.C. */
int hashJoin(Buffer *buf)
{
	/* ---------- phase 1: partition both relations on the join attribute --
	 * Every bucket keeps one block in the buffer while it is being filled,
	 * BUCKET_NUM + 1 blocks are used at a time. Tuples that join end up in
	 * buckets with the same number, so the partitions can be joined pairwise. */
	if (partition(buf, R_ADDR, R_BLK_NUM, HASH_R_ADDR) != 0)
		return -1;
	if (partition(buf, S_ADDR, S_BLK_NUM, HASH_S_ADDR) != 0)
		return -1;

	cout << "R and S partitioned into " << BUCKET_NUM << " buckets ("
	     << HASH_R_ADDR << " and " << HASH_S_ADDR << ")." << endl;

	return 0;
}

