	Relation group[R_NUM]; /* the tuples of R that share the current key */
	int num = 0;

	while (r.alive && s.alive)
	{
		if (scanCur(&r)->attr1 < scanCur(&s)->attr1)
		{
			scanNext(&r, buf); /* no S tuple can match this R tuple */
			continue;
		}
		if (scanCur(&r)->attr1 > scanCur(&s)->attr1)
		{
			scanNext(&s, buf); /* no R tuple can match this S tuple */
			continue;
		}

		/* both sides agree on the key: every tuple of the R group joins with
		 * every tuple of the S group */
		int key = scanCur(&r)->attr1;

		int groupNum = 0;
		while (r.alive && scanCur(&r)->attr1 == key && groupNum < R_NUM)
		{
			group[groupNum++] = *scanCur(&r);
			scanNext(&r, buf);
		}

		/* the S group is streamed, only the R group has to be remembered */
		while (s.alive && scanCur(&s)->attr1 == key)
		{
			for (int i = 0; i < groupNum; i++)
			{
				/* R.A = S.C, so the result keeps A, B and D */
				output(buf, SMJ_RET_ADDR, group[i].attr1, group[i].attr2, scanCur(&s)->attr2);
				num++;
			}
			scanNext(&s, buf);
		}
	}

	/* give the last blocks of both scans back to the buffer */
	if (r.blk != NULL)
		freeBlockInBuffer(r.blk, buf);
	if (s.blk != NULL)
		freeBlockInBuffer(s.blk, buf);

	/* flush the result block that is still being filled */
	pushToWrite(buf, NULL, 0, SMJ_RET_ADDR, false, true);

	int perBlk = (BLK_SIZE - 2 * PTR_SIZE) / sizeof(Relation3);
	if (num > 0)
		cout << endl << "Sort merge join result: " << num << " tuple(s) written to "
		     << SMJ_RET_ADDR << " - " << SMJ_RET_ADDR + (num - 1) / perBlk << endl;
	cout << "Number of block I/O's: " << buf->numIO << endl;

	return num;
}

