#include <iostream>
#include "join.h"
#include "file.h"
#include "blkio.h"
#include "mergeSort.h"

using namespace std;

/* Sequential scan over a sorted relation on the disk. Only the block that is
 * being consumed is kept in the buffer. */
struct SortedScan {
	unsigned int addr;   /* address of the next block to be read */
	int left;            /* number of blocks not read yet */
	unsigned char *blk;  /* block held in the buffer, NULL if none */
	Relation tuple[TUPLE_PER_BLK];
	int pos;             /* tuple to be consumed next */
	bool alive;          /* false once the relation is exhausted */
};

/* Release the current block and load the next one of the relation. */
static bool scanLoad(SortedScan *scan, Buffer *buf)
{
	if (scan->blk != NULL)
	{
		freeBlockInBuffer(scan->blk, buf);
		scan->blk = NULL;
	}
	if (scan->left <= 0 || (scan->blk = readBlockFromDisk(scan->addr, buf)) == NULL)
	{
		scan->alive = false;
		return false;
	}
	scan->addr++;
	scan->left--;
	readTuplesFromBlock(scan->blk, scan->tuple);
	scan->pos = 0;
	scan->alive = true;
	return true;
}

static void scanInit(SortedScan *scan, Buffer *buf, unsigned int addr, int blkNum)
{
	scan->addr = addr;
	scan->left = blkNum;
	scan->blk = NULL;
	scan->pos = 0;
	scan->alive = false;
	scanLoad(scan, buf);
}

/* Step to the next tuple, loading the next block when needed. */
static bool scanNext(SortedScan *scan, Buffer *buf)
{
	if (!scan->alive)
		return false;
	if (++scan->pos < TUPLE_PER_BLK)
		return true;
	return scanLoad(scan, buf);
}

static Relation *scanCur(SortedScan *scan)
{
	return &scan->tuple[scan->pos];
}

/* Sort merge join of R and S on R.A = S.C. */
int sortMergeJoin(Buffer *buf)
{
	/* ---------- preparation: sort both relations on the join attribute ---- */
	if (mergeSort(buf, SORT_R) != 0)
		return -1;
	if (mergeSort(buf, SORT_S) != 0)
		return -1;
	cout << endl;

	/* the sorting used the result writer, restart it for the join */
	pushToWrite(buf, NULL, 0, SMJ_RET_ADDR, true);

	/* load the first block of both sorted relations */
	SortedScan r, s;
	scanInit(&r, buf, MERGE_R_RET_ADDR, R_BLK_NUM);
	scanInit(&s, buf, MERGE_S_RET_ADDR, S_BLK_NUM);

	cout << "Result of R and S joined on R.A = S.C:" << endl;

	return 0;
}

