#include <string.h>
#include <iostream>
#include "blkio.h"
#include "file.h"

using namespace std;

/* Payload capacity of a block: the last two integers of every block are
 * reserved, exactly as in the relation files written by genData.py --
 * a zero separator followed by the address of the next block of the chain
 * (0 marks the last block). */
#define BLK_CAPACITY (BLK_SIZE - 2 * PTR_SIZE)

/* State of the result block that is currently being filled by pushToWrite. */
static unsigned char *writeBlk = NULL; /* block held in the buffer, NULL if none */
static size_t writeUsed = 0;           /* payload bytes already used */
static unsigned int writeAddr = 0;     /* disk address of the pending block */

/* Terminate the pending block with (0, nextAddr) and flush it to the disk.
 * writeBlockToDisk releases the buffer slot for us. */
static void flushWriteBlk(Buffer *buf, unsigned int nextAddr)
{
	int zero = 0;

	memcpy(writeBlk + BLK_SIZE - 2 * PTR_SIZE, &zero, PTR_SIZE);
	memcpy(writeBlk + BLK_SIZE - PTR_SIZE, &nextAddr, PTR_SIZE);
	writeBlockToDisk(writeBlk, writeAddr, buf);

	writeAddr++;
	writeBlk = NULL;
	writeUsed = 0;
}

void pushToWrite(Buffer *buf, unsigned char *source, size_t size, unsigned int addr, bool reset, bool push)
{
	if (reset)
	{
		/* Start a brand new result sequence at addr. Any block that is still
		 * pending is dropped: the buffer it lived in may already be gone, so
		 * we only forget about it here. */
		writeBlk = NULL;
		writeUsed = 0;
		writeAddr = addr;
		return;
	}

	if (push)
	{
		/* Flush whatever is left; this block ends the chain. */
		if (writeBlk != NULL && writeUsed > 0)
			flushWriteBlk(buf, 0);
		return;
	}

	if (source == NULL || size == 0 || size > BLK_CAPACITY)
		return;

	/* The pending block cannot hold one more tuple: flush it and link it to
	 * its successor. Flushing lazily keeps the chain of next addresses valid. */
	if (writeBlk != NULL && writeUsed + size > BLK_CAPACITY)
		flushWriteBlk(buf, writeAddr + 1);

	if (writeBlk == NULL)
	{
		if ((writeBlk = getNewBlockInBuffer(buf)) == NULL)
		{
			perror("Writing Result Fails!\n");
			return;
		}
		memset(writeBlk, 0, BLK_SIZE);
		writeUsed = 0;
	}

	memcpy(writeBlk + writeUsed, source, size);
	writeUsed += size;
}

void readTuplesFromBlock(unsigned char *blk, Relation *R)
{
	/* A relation block stores TUPLE_PER_BLK tuples of two 4 byte integers. */
	for (int i = 0; i < TUPLE_PER_BLK; i++)
	{
		memcpy(&R[i].attr1, blk + i * 2 * PTR_SIZE, PTR_SIZE);
		memcpy(&R[i].attr2, blk + i * 2 * PTR_SIZE + PTR_SIZE, PTR_SIZE);
	}
}

void output(Buffer *buf, unsigned int addr, int attr1, int attr2, int attr3)
{
	Relation3 tuple;

	tuple.attr1 = attr1;
	tuple.attr2 = attr2;
	tuple.attr3 = attr3;

	cout << "(" << attr1 << ", " << attr2 << ", " << attr3 << ")" << endl;

	pushToWrite(buf, (unsigned char *)&tuple, sizeof(Relation3), addr);
}

/* One block of a hash partition holds HASH_PER_BLK tuples, the number of
 * tuples that are actually stored, and the address of the next block of the
 * partition (0 for the last one). Every bucket keeps its own pending block,
 * BUCKET_NUM + 1 blocks are therefore needed in the buffer while
 * partitioning, which fits in the 8 blocks the buffer provides. */
#define HASH_CNT_OFFSET (HASH_PER_BLK * 2 * PTR_SIZE)
/* Partitions are spread out so that every bucket may grow independently. */
#define HASH_BUCKET_STEP 100

static unsigned char *hashBlk[BUCKET_NUM] = { NULL };
static int hashCnt[BUCKET_NUM] = { 0 };
static unsigned int hashAddr[BUCKET_NUM] = { 0 };

/* Complete the pending block of bucket i and flush it to the disk. */
static void flushHashBlk(Buffer *buf, int i, unsigned int nextAddr)
{
	memcpy(hashBlk[i] + HASH_CNT_OFFSET, &hashCnt[i], PTR_SIZE);
	memcpy(hashBlk[i] + BLK_SIZE - PTR_SIZE, &nextAddr, PTR_SIZE);
	writeBlockToDisk(hashBlk[i], hashAddr[i], buf);

	hashAddr[i]++;
	hashBlk[i] = NULL;
	hashCnt[i] = 0;
}

void pushHashToWrite(Buffer *buf, Relation *R, unsigned int addr, bool reset, bool push)
{
	if (reset)
	{
		/* Bucket i is stored in the chain of blocks that starts at
		 * addr + i * HASH_BUCKET_STEP. */
		for (int i = 0; i < BUCKET_NUM; i++)
		{
			hashBlk[i] = NULL;
			hashCnt[i] = 0;
			hashAddr[i] = addr + i * HASH_BUCKET_STEP;
		}
		return;
	}

	if (push)
	{
		/* Flush the last block of every bucket. */
		for (int i = 0; i < BUCKET_NUM; i++)
			if (hashBlk[i] != NULL && hashCnt[i] > 0)
				flushHashBlk(buf, i, 0);
		return;
	}

	if (R == NULL)
		return;

	int bucket = R->attr1 % BUCKET_NUM; /* hash function on the join attribute */

	if (hashBlk[bucket] != NULL && hashCnt[bucket] >= HASH_PER_BLK)
		flushHashBlk(buf, bucket, hashAddr[bucket] + 1);

	if (hashBlk[bucket] == NULL)
	{
		if ((hashBlk[bucket] = getNewBlockInBuffer(buf)) == NULL)
		{
			perror("Writing Hash Partition Fails!\n");
			return;
		}
		memset(hashBlk[bucket], 0, BLK_SIZE);
		hashCnt[bucket] = 0;
	}

	unsigned char *slot = hashBlk[bucket] + hashCnt[bucket] * 2 * PTR_SIZE;
	memcpy(slot, &R->attr1, PTR_SIZE);
	memcpy(slot + PTR_SIZE, &R->attr2, PTR_SIZE);
	hashCnt[bucket]++;
}

int readHashFromBlock(unsigned char *blk, Relation *R)
{
	int count = 0;

	memcpy(&count, blk + HASH_CNT_OFFSET, PTR_SIZE);
	if (count < 0 || count > HASH_PER_BLK)
		count = HASH_PER_BLK; /* defensive: treat a broken header as a full block */

	for (int i = 0; i < count; i++)
	{
		memcpy(&R[i].attr1, blk + i * 2 * PTR_SIZE, PTR_SIZE);
		memcpy(&R[i].attr2, blk + i * 2 * PTR_SIZE + PTR_SIZE, PTR_SIZE);
	}

	return count;
}

